import{_ as i,o as t,c as a,ae as l}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),r={name:"architecture.md"};function o(n,e,s,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>SocioProphet is structured around three principles:</p><ol><li>Client-visible configuration is public by design.</li><li>Datastore access is deny-by-default.</li><li>Security invariants are test-backed.</li></ol><hr><h2 id="system-components" tabindex="-1">System Components <a class="header-anchor" href="#system-components" aria-label="Permalink to &quot;System Components&quot;">​</a></h2><h3 id="_1-web-client-socioprophet-web-client" tabindex="-1">1. Web Client (<code>socioprophet-web/client</code>) <a class="header-anchor" href="#_1-web-client-socioprophet-web-client" aria-label="Permalink to &quot;1. Web Client (`socioprophet-web/client`)&quot;">​</a></h3><ul><li>Webpack-built frontend</li><li>Loads Firebase configuration at runtime from <code>public/firebase-config.js</code></li><li>Does not embed environment variables into build artifacts</li></ul><h3 id="_2-firestore" tabindex="-1">2. Firestore <a class="header-anchor" href="#_2-firestore" aria-label="Permalink to &quot;2. Firestore&quot;">​</a></h3><ul><li>Rules-as-code (<code>socioprophet-web/firestore.rules</code>)</li><li>Deny-by-default policy</li><li>Explicit allow rules only (when backed by tests)</li><li>Emulator-backed tests enforce invariants</li></ul><h3 id="_3-ci-guardrails" tabindex="-1">3. CI Guardrails <a class="header-anchor" href="#_3-ci-guardrails" aria-label="Permalink to &quot;3. CI Guardrails&quot;">​</a></h3><ul><li>Gitleaks scanning in CI</li><li>Firestore emulator rules tests in CI</li><li>CodeQL static analysis</li></ul><hr><h2 id="runtime-configuration-model" tabindex="-1">Runtime Configuration Model <a class="header-anchor" href="#runtime-configuration-model" aria-label="Permalink to &quot;Runtime Configuration Model&quot;">​</a></h2><p>Instead of injecting environment variables into the bundle, the client loads a runtime config file:</p><ul><li><code>socioprophet-web/client/public/firebase-config.js</code></li></ul><p>This file defines:</p><ul><li><code>window.__FIREBASE_CONFIG__</code></li></ul><p>This prevents:</p><ul><li>Build-time secret taint</li><li>CodeQL build-artifact leak alerts</li><li>Accidental secret bundling</li></ul><hr><h2 id="security-flow" tabindex="-1">Security Flow <a class="header-anchor" href="#security-flow" aria-label="Permalink to &quot;Security Flow&quot;">​</a></h2><p>Developer → Git → CI → Emulator Tests → Merge → Deploy</p><p>Rules changes cannot merge unless:</p><ul><li>emulator rules tests pass</li><li>secret scanning passes</li><li>CodeQL passes (no new alerts)</li></ul><hr><h2 id="knowledge-commons-direction" tabindex="-1">Knowledge Commons Direction <a class="header-anchor" href="#knowledge-commons-direction" aria-label="Permalink to &quot;Knowledge Commons Direction&quot;">​</a></h2><p>This repository currently contains:</p><ul><li>Web interface scaffolding</li><li>Security enforcement primitives</li><li>Configuration discipline</li></ul><p>Planned layers (as the system stabilizes):</p><ul><li>Knowledge graph / datastore abstraction</li><li>Interoperable export formats</li><li>Provenance and attribution</li><li>Local-first sync and federation model</li><li>Governance and contribution crediting</li></ul><p>This document will evolve as the architecture hardens.</p>',31)])])}const m=i(r,[["render",o]]);export{p as __pageData,m as default};
